<script setup>
import { reactive,ref,computed,onMounted,watch } from 'vue';
import { useRoute,useRouter } from 'vue-router';
import { api } from '../../services/api.js';
import { workspace,loadStores } from '../../services/workspace.js';
import { canFeature } from '../../services/auth.js';
import { notify,confirmDialog } from '../../services/notifications.js';
import { money } from '../../services/panel.js';
import Icon from '../../components/Icon.vue';
import DataTable from '../../components/DataTable.vue';
const route=useRoute(),router=useRouter(),origin=window.location.origin,loading=ref(true),saving=ref(false),error=ref(''),tab=ref(String(route.query.tab||'pagos'));
const store=ref(null),credentials=reactive({accessToken:'',webhookSecret:'',sandbox:true,clearCredentials:false}),configured=reactive({hasAccessToken:false,hasWebhookSecret:false});
const paymentTypes={cash:'Efectivo',transfer:'Transferencia',mercadopago:'Mercado Pago'},deliveryTypes={pickup:'Retiro',shipping:'Envío',digital:'Digital',custom:'Personalizada'};
const paymentColumns=[{key:'name',label:'Forma de pago'},{key:'type',label:'Tipo'},{key:'deliveryIds',label:'Disponible para'},{key:'active',label:'Estado'}],deliveryColumns=[{key:'name',label:'Entrega'},{key:'type',label:'Tipo'},{key:'price',label:'Costo'},{key:'active',label:'Estado'}];
const visiblePayments=computed(()=>store.value?.payments?.filter(payment=>payment.type!=='mercadopago'||canFeature('payments.mercadopago'))||[]);
function normalizeTab(value){if(value==='mercadopago'&&!canFeature('payments.mercadopago'))return 'pagos';return ['pagos','entregas','mercadopago'].includes(value)?value:'pagos'}
watch(tab,value=>{const safe=normalizeTab(value);if(safe!==value){tab.value=safe;return}router.replace({query:{tab:value}})});
onMounted(()=>{tab.value=normalizeTab(tab.value);load()});
async function load(){try{store.value=await api.get(`/stores/${workspace.activeStoreId}`);const mp=store.value.integrations?.mercadopago||{};Object.assign(configured,{hasAccessToken:!!mp.hasAccessToken,hasWebhookSecret:!!mp.hasWebhookSecret});Object.assign(credentials,{sandbox:mp.sandbox??true,accessToken:'',webhookSecret:'',clearCredentials:false});}catch(e){error.value=e.message}finally{loading.value=false}}
async function remove(kind,row){if(!await confirmDialog({title:kind==='payments'?'Quitar forma de pago':'Quitar forma de entrega',message:'Dejará de ofrecerse en nuevas compras. Los pedidos existentes conservarán su información. Podés desactivarla desde Editar si preferís conservar su configuración.',confirmText:'Quitar',danger:true}))return;saving.value=true;try{const latest=await api.get(`/stores/${workspace.activeStoreId}`);if(kind==='deliveries'&&latest.payments.some(p=>p.deliveryIds.includes(row.id)))throw new Error('Esta entrega está asociada a un medio de pago. Editá primero esa forma de pago para quitar la asociación.');const payload={payments:latest.payments,deliveries:latest.deliveries,expectedUpdatedAt:latest.updatedAt};payload[kind]=payload[kind].filter(x=>x.id!==row.id);await api.put(`/stores/${workspace.activeStoreId}/payments`,payload);notify.success('Opción eliminada.');await load();await loadStores()}catch(e){notify.error(e.message)}finally{saving.value=false}}
async function saveCredentials(){saving.value=true;error.value='';try{const latest=await api.get(`/stores/${workspace.activeStoreId}`),mp={sandbox:credentials.sandbox,clearCredentials:credentials.clearCredentials};if(credentials.accessToken.trim())mp.accessToken=credentials.accessToken.trim();if(credentials.webhookSecret.trim())mp.webhookSecret=credentials.webhookSecret.trim();await api.put(`/stores/${workspace.activeStoreId}/payments`,{payments:latest.payments,deliveries:latest.deliveries,mercadopago:mp,expectedUpdatedAt:latest.updatedAt});notify.success('Configuración de Mercado Pago guardada.');await load()}catch(e){error.value=e.message;notify.error(e.message)}finally{saving.value=false}}
function deliveryNames(ids){return ids.length?ids.map(id=>store.value.deliveries.find(d=>d.id===id)?.name||'Entrega no disponible').join(', '):'Todas las entregas'}
</script>
<template><div><header class="p-page-header"><div><p class="p-eyebrow">UNA COMPRA SIMPLE, DE PRINCIPIO A FIN</p><h1>Cobros y entregas</h1><p>Ofrecé opciones claras y decidí qué medios de pago están disponibles para cada entrega.</p></div></header><div v-if="error" class="p-error">{{error}}</div><div v-if="loading" class="p-loading-page"><span class="p-spinner"/></div><template v-else-if="store"><nav class="p-tabs" aria-label="Opciones de cobros y entrega"><button type="button" :class="{active:tab==='pagos'}" @click="tab='pagos'"><Icon name="credit" :size="16"/>Formas de pago</button><button  type="button" :class="{active:tab==='entregas'}" @click="tab='entregas'"><Icon name="truck" :size="16"/>Formas de entrega</button><button v-if="canFeature('payments.mercadopago')" type="button" :class="{active:tab==='mercadopago'}" @click="tab='mercadopago'"><Icon name="shield" :size="16"/>Mercado Pago</button></nav><section v-if="tab==='pagos'"><div class="p-section-title"><div><h2>Formas de pago</h2><p>Podés activar varias y definir cuándo ofrecerlas.</p></div><RouterLink to="/app/payments/methods/new" class="btn btn-primary"><Icon name="plus" :size="15"/>Agregar pago</RouterLink></div><DataTable :rows="visiblePayments" :columns="paymentColumns" :loading="saving" empty-text="Agregá tu primera forma de pago."><template #cell-name="{row}"><div class="p-product-cell"><span class="p-product-thumb"><Icon name="credit" :size="18"/></span><strong>{{row.name}}</strong></div></template><template #cell-type="{value}">{{paymentTypes[value]}}</template><template #cell-deliveryIds="{value}"><span class="p-break" style="display:block;max-width:280px">{{deliveryNames(value)}}</span></template><template #cell-active="{value}"><span class="p-badge dot" :class="value?'green':'orange'">{{value?'Habilitada':'Deshabilitada'}}</span></template><template #actions="{row}"><RouterLink :to="`/app/payments/methods/${row.id}`" class="p-icon-btn" title="Editar medio de pago"><Icon name="edit" :size="14"/></RouterLink><button class="p-icon-btn danger" title="Quitar medio de pago" @click="remove('payments',row)"><Icon name="trash" :size="14"/></button></template></DataTable><div class="p-info">Ejemplo: configurá Efectivo y seleccioná únicamente Retiro en el local. En el checkout solo se ofrecerá al elegir esa entrega.</div></section><section v-else-if="tab==='entregas'"><div class="p-section-title"><div><h2>Formas de entrega</h2><p>Costos e instrucciones para cada alternativa.</p></div><RouterLink  to="/app/payments/deliveries/new" class="btn btn-primary"><Icon name="plus" :size="15"/>Agregar entrega</RouterLink></div><DataTable :rows="store.deliveries" :columns="deliveryColumns" :loading="saving" empty-text="Elegí cómo van a llegar tus productos."><template #cell-name="{row}"><div class="p-product-cell"><span class="p-product-thumb"><Icon name="truck" :size="18"/></span><strong>{{row.name}}</strong></div></template><template #cell-type="{value}">{{deliveryTypes[value]}}</template><template #cell-price="{value}"><strong>{{Number(value)===0?'Gratis':money(value)}}</strong></template><template #cell-active="{value}"><span class="p-badge dot" :class="value?'green':'orange'">{{value?'Habilitada':'Deshabilitada'}}</span></template><template #actions="{row}"><RouterLink :to="`/app/payments/deliveries/${row.id}`" class="p-icon-btn" title="Editar entrega"><Icon name="edit" :size="14"/></RouterLink><button class="p-icon-btn danger" title="Quitar entrega" @click="remove('deliveries',row)"><Icon name="trash" :size="14"/></button></template></DataTable></section><form v-else-if="tab==='mercadopago'&&canFeature('payments.mercadopago')" @submit.prevent="saveCredentials"><section class="p-section-card"><div class="p-section-title"><div><h2>Mercado Pago · Checkout Pro</h2><p>Conectá la cuenta que recibirá los cobros de esta tienda.</p></div><span class="p-badge" :class="configured.hasAccessToken&&configured.hasWebhookSecret?'green':'orange'">{{configured.hasAccessToken&&configured.hasWebhookSecret?'Credenciales guardadas':'Pendiente de configurar'}}</span></div><div class="p-info">Obtené el Access Token y la clave secreta de Webhooks desde la aplicación de Mercado Pago del vendedor. Cada tienda conserva sus propias credenciales.</div><div class="p-form-grid"><div class="p-field full"><label for="mp-token">Access Token</label><input id="mp-token" v-model="credentials.accessToken" type="password" autocomplete="new-password" :placeholder="configured.hasAccessToken?'Configurado · dejá vacío para conservarlo':'APP_USR-... o TEST-...'"/><small>Se guarda cifrado. No se devuelve al navegador después de guardarlo.</small></div><div class="p-field full"><label for="mp-secret">Clave secreta de Webhooks</label><input id="mp-secret" v-model="credentials.webhookSecret" type="password" autocomplete="new-password" :placeholder="configured.hasWebhookSecret?'Configurada · dejá vacío para conservarla':'Clave secreta de la aplicación'"/></div><div class="p-field full"><label>URL de notificaciones de esta tienda</label><code style="font-size:11px;background:#f4f7f9;padding:12px;border-radius:6px;overflow-wrap:anywhere">{{origin}}/api/webhooks/mercadopago/{{workspace.activeStoreId}}</code><small>Usá el dominio público con HTTPS en producción. Suscribí la aplicación al evento de pagos.</small></div><label class="p-check"><input v-model="credentials.sandbox" type="checkbox"/>Modo de prueba (sandbox)</label><label v-if="configured.hasAccessToken||configured.hasWebhookSecret" class="p-check"><input v-model="credentials.clearCredentials" type="checkbox"/>Borrar credenciales al guardar</label></div><div v-if="credentials.clearCredentials" class="p-info p-warning">Se quitarán las credenciales de Mercado Pago. Deshabilitá las formas de pago asociadas antes de continuar.</div></section><footer class="p-form-footer"><small>Los campos vacíos conservan las credenciales existentes.</small><div class="p-form-actions"><button class="btn btn-primary" :disabled="saving">{{saving?'Guardando...':'Guardar Mercado Pago'}}</button></div></footer></form></template></div></template>
